#!/usr/bin/env bash
# اجرا پس از «npx cap add android»؛ آیکن داخل همین فایل است
set -e
R="${1:-android/app/src/main/res}"
rm -f "$R"/mipmap-*/ic_launcher*.png "$R"/mipmap-*/ic_launcher*.webp "$R"/mipmap-*/ic_launcher*.xml
rm -f "$R"/drawable*/ic_launcher_background.xml "$R"/drawable*/ic_launcher_foreground.xml "$R"/values/ic_launcher_background.xml
sed -n '/^__ICON__$/,$p' "$0" | tail -n +2 | base64 -d | tar xzf - -C "$R"
echo "icon applied -> $R"
exit 0
__ICON__

